import numpy as np
def read_xyz(fn):
    lines = open(fn).read().splitlines()
    n = int(lines[0])
    els, pos = [], []
    for l in lines[2:2+n]:
        p = l.split()
        els.append(p[0]); pos.append([float(x) for x in p[1:4]])
    return els, np.array(pos)
els, pos = read_xyz('opt1.xyz')
Ru = pos[0]
lig = {'P1':1, 'P2arm':11, 'Si':12, 'P3':19, 'P4':20}
vecs = {k: pos[i]-Ru for k,i in lig.items()}
names = list(lig)
for a in range(len(names)):
    for b in range(a+1, len(names)):
        va, vb = vecs[names[a]], vecs[names[b]]
        cos = np.dot(va,vb)/np.linalg.norm(va)/np.linalg.norm(vb)
        print(f'{names[a]:6s}-Ru-{names[b]:6s} {np.degrees(np.arccos(np.clip(cos,-1,1))):7.1f}')
