import numpy as np
def read_xyz(fn):
    lines = open(fn).read().splitlines()
    n = int(lines[0])
    els, pos = [], []
    for l in lines[2:2+n]:
        p = l.split()
        els.append(p[0]); pos.append([float(x) for x in p[1:4]])
    return els, np.array(pos)
els, pos = read_xyz('opt2.xyz')
def d(i,j): return np.linalg.norm(pos[i]-pos[j])
# clash check
bs = set(tuple(sorted(p)) for p in [(0,1),(0,11),(0,12),(0,19),(0,20),(1,2),(1,6),(2,3),(3,4),(4,5),(5,6),(5,7),(7,8),(8,9),(9,10),(10,6),(2,11),(12,10),(12,13),(12,1),(13,14),(14,15),(15,16),(16,17),(17,18),(18,13),(14,19)])
n=len(els); hh=[]
for i in range(n):
    if els[i]=='H': continue
    for j in range(i+1,n):
        if els[j]=='H': continue
        dd=d(i,j)
        if (i,j) not in bs and dd<2.2: hh.append((dd,els[i],i,els[j],j))
hh.sort()
print('heavy nonbonded < 2.2:')
for w in hh: print(f'{w[0]:.3f} {w[1]}:{w[2]} - {w[3]}:{w[4]}')
print()
for k,(i,j) in {'Ru-P1':(0,1),'Ru-P2':(0,11),'Ru-P3':(0,19),'Ru-P4':(0,20),'Ru-Si':(0,12),'Si-P1':(12,1),'Si-C8':(12,10),'Si-Ciph':(12,13)}.items():
    print(f'{k:8s} {d(i,j):.3f}')
"
